void require(bool okay,const char* text){if(!okay)throw std::runtime_error(text);}
const std::vector<std::string> styles={"none","thin","medium","dashed","dotted","thick","double","hair","mediumDashed","dashDot","mediumDashDot","dashDotDot","mediumDashDotDot","slantDashDot"};
Json edge(const std::string& style){return {{"style",style},{"color","#a31515"}};}
void validation(){
 for(const auto& style:styles){const Json patch={{"border",{{"top",edge(style)}}}};require(validatedWorksheetCellStyle(patch)==patch,"every native standard border style must pass the same UI validation as Session and OOXML");}
 bool rejected=false;try{validatedWorksheetCellStyle({{"border",{{"top",edge("invalid-style")}}}});}catch(const std::invalid_argument&){rejected=true;}require(rejected,"unknown border styles remain rejected");
 rejected=false;try{validatedWorksheetCellStyle({{"border",{{"top",{{"style",4},{"color","#000000"}}}}}});}catch(const std::invalid_argument&){rejected=true;}require(rejected,"non-text line styles remain rejected");
}
void rendering(){
 WorkbookSession session;WorksheetModel model(session);WorksheetView view;view.setModel(&model);view.resize(700,400);view.setShowGrid(false);view.horizontalHeader()->setDefaultSectionSize(180);view.verticalHeader()->setDefaultSectionSize(40);view.setCurrentIndex(model.index(7,3));view.show();
 for(int row=2;row<=5;++row)require(model.apply(Json::array({{{"type","set_cell"},{"sheet",model.sheetId().toStdString()},{"row",row},{"col",2},{"input",""},{"style",{{"border",{{"top",edge(std::vector<std::string>{"thin","thick","double","dashed"}[row-2])}}}}}}})),"seed actual imported native border style");
 QApplication::processEvents();const auto before=session.snapshot();const auto image=view.viewport()->grab().toImage();auto colored=[&](int row){const auto rect=view.visualRect(model.index(row-1,1));int count=0;for(int y=rect.top()-3;y<=rect.top()+1;++y)if(image.pixelColor(rect.center().x(),y)==QColor("#a31515"))++count;return count;};
 require(colored(2)==1&&colored(3)==3,"actual grid rendering distinguishes the thin one-pixel border from the three-pixel thick border");const auto doubleRect=view.visualRect(model.index(3,1));require(colored(4)==2&&image.pixelColor(doubleRect.center().x(),doubleRect.top()-1)!=QColor("#a31515"),"actual double border has two lines separated by a visible gap");const auto dashedRect=view.visualRect(model.index(4,1));int marks=0;for(int x=dashedRect.left()+5;x<dashedRect.right()-5;++x)if(image.pixelColor(x,dashedRect.top()-1)==QColor("#a31515"))++marks;require(marks>30&&marks<dashedRect.width()-25,"native dashed borders have visible runs and gaps rather than a solid thin substitute");require(session.snapshot()==before,"painting native border weights and patterns never changes workbook data/history");
}
void axes(){
 WorkbookSession session;WorksheetModel model(session);WorksheetView view;view.setModel(&model);view.resize(700,300);view.setShowGrid(false);view.horizontalHeader()->setDefaultSectionSize(180);view.verticalHeader()->setDefaultSectionSize(40);view.setCurrentIndex(model.index(5,2));view.show();
 for(const auto* kind:{"medium","thick","double"}){Json border=Json::object();for(const auto* side:{"top","bottom","left","right"})border[side]=edge(kind);require(model.apply(Json::array({{{"type","set_cell"},{"sheet",model.sheetId().toStdString()},{"row",2},{"col",2},{"input",""},{"style",{{"border",border}}}}})),"seed four native border axes");QApplication::processEvents();const auto rect=view.visualRect(model.index(1,1));const auto image=view.viewport()->grab().toImage();const auto ink=QColor("#a31515");for(const auto& [x,y,horizontal]:std::vector<std::tuple<int,int,bool>>{{rect.center().x(),rect.top()-1,true},{rect.center().x(),rect.bottom(),true},{rect.left()-1,rect.center().y(),false},{rect.right(),rect.center().y(),false}}){if(std::string_view(kind)=="double")require(image.pixelColor(x-(horizontal?0:1),y-(horizontal?1:0))==ink&&image.pixelColor(x+(horizontal?0:1),y+(horizontal?1:0))==ink&&image.pixelColor(x,y)!=ink,"double borders preserve two physical-edge strokes with a center gap on all axes");else require(image.pixelColor(x,y)==ink,"every native weight reaches the canonical physical boundary on all four axes");}}
}
